// 데이터 검증 및 변환

const data = items[0].json.body || items[0].json;
console.log('Received data:', data);

// 필수 항목 체크 (실제 받은 필드명 기준)
const requiredFields = ['branch', 'date', 'time', 'spaceType', 'guests', 'name', 'phone', 'email', 'language'];
const missingFields = [];

for (const field of requiredFields) {
  if (!data[field] || data[field].toString().trim() === '') {
    missingFields.push(field);
  }
}

console.log('Missing fields:', missingFields);

if (missingFields.length > 0) {
  return [{
    json: {
      error: true,
      message: `Missing required fields: ${missingFields.join(', ')}`,
      receivedData: data
    }
  }];
}

// 이메일 형식 검증
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(data.email)) {
  return [{
    json: {
      error: true,
      message: 'Invalid email format'
    }
  }];
}

// 날짜/시간 형식 변환
const dateTime = `${data.date}T${data.time}:00.000+07:00`; // Bangkok timezone

// 예약번호 생성용 날짜 (YYYYMMDD)
const bookingDate = data.date.replace(/-/g, '');

// 공간 정보 설정
let roomNumber = null;
let floor = null;

if (data.spaceType === 'Room') {
  roomNumber = data.spaceDetail;
} else {
  floor = data.spaceDetail;
}

// 영수증 확인 (receiptBase64 포함)
const hasReceipt = data.receipt || data.depositReceipt || data.receiptBase64;

// Status 결정 (Room + 영수증 있으면 즉시 Confirmed)
const status = (data.spaceType === 'Room' && hasReceipt) ? 'Confirmed' :
               (data.spaceType === 'Table') ? 'Confirmed' : 'Pending';

return [{
  json: {
    ...data,
    dateTime: dateTime,
    bookingDate: bookingDate,
    roomNumber: roomNumber,
    floor: floor,
    status: status,
    hasDepositReceipt: !!hasReceipt,
    reminderSent: false,
    error: false
  }
}];

// 예약번호 생성 (원래 데이터 유지)
const uploadFileData = items[0].json; // Google Drive 파일 정보 (Table 예약일 경우 없을 수 있음)
const originalData = $('데이터 검증').item.json; // 원래 예약 데이터

console.log('===== 예약번호 생성 시작 =====');
console.log('uploadFileData:', JSON.stringify(uploadFileData, null, 2));
console.log('originalData:', JSON.stringify(originalData, null, 2));

// 원래 데이터 사용 (Upload file 데이터는 파일 정보만)
const data = originalData;

// 안전한 날짜 처리
let dateForBooking = '';
if (data.date) {
  dateForBooking = data.date.replace(/-/g, '');
} else if (data.bookingDate) {
  dateForBooking = data.bookingDate;
} else {
  const today = new Date();
  dateForBooking = today.getFullYear() +
    String(today.getMonth() + 1).padStart(2, '0') +
    String(today.getDate()).padStart(2, '0');
}

// 시퀀스 번호 생성
const sequence = String(Date.now()).slice(-3);

// 예약번호 생성
const bookingNumber = `BOOK-${dateForBooking}-${sequence}`;

console.log('Generated booking number:', bookingNumber);

// Deposit Receipt 파일 배열 생성 (Notion 노드에서 바로 사용 가능)
let depositReceiptFiles = [];

// Room 예약이고 Upload file 노드가 성공한 경우에만 파일 정보 추가
if (data.spaceType === 'Room' && uploadFileData && uploadFileData.name && uploadFileData.webViewLink) {
  depositReceiptFiles = [{
    name: uploadFileData.name || 'receipt',
    url: uploadFileData.webViewLink
  }];
}

// Table 예약이거나 영수증이 없으면 빈 배열 []

// 출력 데이터 생성: 원래 데이터 + 예약번호 + Deposit Receipt 파일 배열
const outputData = {
  ...data,
  bookingNumber: bookingNumber,
  depositReceiptFiles: depositReceiptFiles  // Notion 노드에서 바로 사용 가능한 형태
};

console.log('===== 출력 데이터 =====');
console.log('outputData:', JSON.stringify(outputData, null, 2));

return [{
  json: outputData
}];

// 관리자 이메일 템플릿 (태국어 고정, 안전 처리)
const data = items[0].json;

const branchInfo = {
  'Ekamai': {
    name: 'สาขาเอกมัย',
    phone: '095-868-6826',
    address: 'BTS เอกมัย ทางออก 4 ตรงข้ามโรงพยาบาลสุขุมวิท'
  },
  'Phrom Phong': {
    name: 'สาขาพร้อมพงษ์', 
    phone: '02-115-5500',
    address: 'สุขุมวิท ซอย 24 ชั้น 1 โรงแรมอริสตัน'
  }
};

// 디버깅 정보
console.log('=== Branch Debug ===');
console.log('data.property_branch:', JSON.stringify(data.property_branch));
console.log('branchInfo keys:', Object.keys(branchInfo));

// 안전한 지점 정보 가져오기 (올바른 속성명 사용)
let branch = branchInfo[data.property_branch];
console.log('branch result:', branch);

if (!branch) {
  console.error('Branch not found! Available branches:', Object.keys(branchInfo));
  console.error('Received branch:', data.property_branch);

  // 기본값 설정 (오류 방지)
  branch = {
    name: data.property_branch + ' (정보 없음)',
    phone: '연락처 정보 없음',
    address: '주소 정보 없음'
