// 날짜 포맷팅 (올바른 속성명 사용)
const dateFormatted = new Date(data.property_reservation_date_time.start).toLocaleString('th-TH', {
  timeZone: 'Asia/Bangkok',
  year: 'numeric',
  month: '2-digit', 
  day: '2-digit',
