    cancelUrl: cancelUrl
  }
}];

// Calculate tomorrow's date
const today = new Date();
const tomorrow = new Date(today);
tomorrow.setDate(tomorrow.getDate() + 1);

// Convert to Bangkok timezone
const bangkokTime = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Bangkok',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(tomorrow);

return [{
  json: {
    tomorrowDate: bangkokTime,
    searchStartDate: `${bangkokTime}T00:00:00.000+07:00`,
    searchEndDate: `${bangkokTime}T23:59:59.999+07:00`
  }
}];

// Prepare reminder data (data is already extracted from Notion)
const reservations = items
  .filter(item => {
    const data = item.json;
    const email = data.property_email;
    // 이메일이 있고 비어있지 않은 항목만 필터링
    return email && email.trim() !== '';
  })
  .map(item => {
