parameters.functionCode:
// 🎯 입력값 파싱 및 검증
const queryParams = $input.item.json.query;

const date = queryParams.date;
const branch = queryParams.branch;
const room = queryParams.room;

// 검증
if (!date || !branch || !room) {
  return {
    json: {
      error: 'Missing required parameters: date, branch, room',
      blockedSlots: []
    }
  };
}

// Room이 아니면 빈 배열 반환 (Table은 중복 체크 안 함)
if (!room.includes('Room')) {
  return {
    json: {
      date,
      branch,
      room,
      bookedTimes: [],
      blockedSlots: [],
      message: 'Table reservations do not require time blocking'
    }
  };
}

// Notion 쿼리용 데이터 반환
return {
  json: {
    date,
    branch,
    room,
    // Notion에서 검색할 날짜 범위 (해당 날짜 전체)
    dateStart: `${date}T00:00:00+07:00`,
    dateEnd: `${date}T23:59:59+07:00`
  }
};

// 🎯 예약된 시간을 3시간 블록으로 계산 (브레이크 타임 고려)
const items = $input.all();
const bookedTimes = [];
const blockedSlots = new Set();

// 브레이크 타임: 15:00-16:00
const BREAK_START_MINUTES = 15 * 60; // 900분
const BREAK_END_MINUTES = 16 * 60; // 960분

// 데이터가 없으면 빈 결과 반환
if (!items || items.length === 0) {
  return {
    json: {
      date: $('Parse Query Parameters').item.json.date,
      branch: $('Parse Query Parameters').item.json.branch,
      room: $('Parse Query Parameters').item.json.room,
      bookedTimes: [],
      blockedSlots: [],
      totalReservations: 0,
      totalBlockedSlots: 0,
      message: 'No existing reservations found'
    }
  };
}

// 예약된 시간 추출
for (const item of items) {
  // 데이터 체크
  if (!item.json) {
    continue;
  }

  // property_reservation_date_time 필드에서 시간 추출
  const dateTimeValue = item.json.property_reservation_date_time?.start;

  if (dateTimeValue) {
    // ISO 8601 형식에서 시간 추출 (HH:MM)
    const timeValue = dateTimeValue.split('T')[1]?.substring(0, 5);

    if (timeValue) {
      bookedTimes.push(timeValue);

      // 3시간 블록 계산 (프론트엔드 calculateAvailableHours 로직과 동일)
      const [hour, minute] = timeValue.split(':').map(Number);
      const startMinutes = hour * 60 + minute;

      // 기본 종료 시간: 시작 시간 + 3시간
      let endMinutes = startMinutes + 180;

      // 브레이크 타임 체크: 시작 시간이 브레이크 타임 이전이고 종료 시간이 브레이크 타임 이후면 브레이크 타임까지만 사용
      if (startMinutes < BREAK_START_MINUTES && endMinutes > BREAK_START_MINUTES) {
        endMinutes = BREAK_START_MINUTES; // 브레이크 타임(15:00)까지만 블록
      }

      // 영업 종료 시간 체크 (22:00)
      const closeMinutes = 22 * 60;
      if (endMinutes > closeMinutes) {
        endMinutes = closeMinutes;
      }

      // 시작 시간부터 종료 시간까지 30분 단위로 블록
      for (let offset = 0; offset <= (endMinutes - startMinutes); offset += 30) {
        const totalMinutes = startMinutes + offset;
        const blockHour = Math.floor(totalMinutes / 60);
        const blockMinute = totalMinutes % 60;

        if (blockHour >= 0 && blockHour < 24) {
          const timeSlot = `${blockHour.toString().padStart(2, '0')}:${blockMinute.toString().padStart(2, '0')}`;
          blockedSlots.add(timeSlot);
        }
      }
    }
  }
}

// Set을 Array로 변환하고 정렬
const blockedArray = Array.from(blockedSlots).sort();

return {
  json: {
    date: $('Parse Query Parameters').item.json.date,
    branch: $('Parse Query Parameters').item.json.branch,
    room: $('Parse Query Parameters').item.json.room,
    bookedTimes: bookedTimes.sort(),
    blockedSlots: blockedArray,
    totalReservations: bookedTimes.length,
    totalBlockedSlots: blockedArray.length
  }
};

