try {
  if (reservationDateTime.includes('T')) {
    dateTime = new Date(reservationDateTime);
  } else {
    dateTime = new Date(reservationDateTime + 'T00:00:00');
  }

  if (isNaN(dateTime.getTime())) {
    dateTime = new Date();
    dateTime.setDate(dateTime.getDate() + 1);
    console.log('Using tomorrow as fallback');
  }
} catch (error) {
  console.log('Date parsing error:', error);
  dateTime = new Date();
  dateTime.setDate(dateTime.getDate() + 1);
}

