const uploadFileData = items[0].json; // Google Drive 파일 정보 (Table 예약일 경우 없을 수 있음)
const originalData = $('데이터 검증').item.json; // 원래 예약 데이터

console.log('===== 예약번호 생성 시작 =====');
console.log('uploadFileData:', JSON.stringify(uploadFileData, null, 2));
console.log('originalData:', JSON.stringify(originalData, null, 2));

// 원래 데이터 사용 (Upload file 데이터는 파일 정보만)
const data = originalData;

// 안전한 날짜 처리
let dateForBooking = '';
if (data.date) {
  dateForBooking = data.date.replace(/-/g, '');
} else if (data.bookingDate) {
  dateForBooking = data.bookingDate;
} else {
  const today = new Date();
  dateForBooking = today.getFullYear() +
    String(today.getMonth() + 1).padStart(2, '0') +
    String(today.getDate()).padStart(2, '0');
}

// 시퀀스 번호 생성
const sequence = String(Date.now()).slice(-3);

// 예약번호 생성
const bookingNumber = `BOOK-${dateForBooking}-${sequence}`;

console.log('Generated booking number:', bookingNumber);

// Deposit Receipt 파일 배열 생성 (Notion 노드에서 바로 사용 가능)
let depositReceiptFiles = [];

